var CURRENCY_SYMBOLS = {
  USD: '$', PAB: 'B/.', CRC: '\u20A1', GTQ: 'Q', HNL: 'L', NIO: 'C$', DOP: 'RD$', MXN: '$', EUR: '\u20AC'
};

function esc(s) {
  if (s === null || s === undefined) return '';
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}
function escAllowSmall(s) {
  return esc(s)
    .replace(/&lt;small&gt;/g, '<small>')
    .replace(/&lt;\/small&gt;/g, '</small>');
}

function detectBarcodeFormat(value) {
  if (!value) return 'CODE128';
  var v = String(value).replace(/\s+/g, '');
  if (/^\d{13}$/.test(v)) return 'EAN13';
  if (/^\d{12}$/.test(v)) return 'UPC';
  if (/^\d{8}$/.test(v)) return 'EAN8';
  return 'CODE128';
}


/* ===================== saved-doc overlay (shared by ACC + catalog) ===================== */
/* Overlay a product_sheets spec doc's custom layer onto live DB-derived spec groups.
 * Standard rows stay live from the DB; custom rows/groups append. Identical to the
 * merge the ACC editor uses on load — so ACC and catalog render the same sheet. */
export function mergeCustom(base, custom) {
  var out = (base || []).map(function (g) { return { title: g.title, rows: (g.rows || []).slice() }; });
  (custom || []).forEach(function (cg) {
    var t = out.filter(function (g) { return g.title === cg.title; })[0];
    if (t) { (cg.rows || []).forEach(function (r) { t.rows.push({ label: r.label || '', value: r.value || '' }); }); }
    else { out.push({ title: cg.title || '', rows: (cg.rows || []).map(function (r) { return { label: r.label || '', value: r.value || '' }; }) }); }
  });
  return out;
}
/* Apply a saved spec doc ({ productImg, custom }) onto a canonical object from
 * productToSheetData. Returns a new object; price/cost never lives in the doc. */
export function applySpecDoc(data, docData) {
  if (!data) return data;
  var d = Object.assign({}, data);
  if (docData) {
    if (docData.productImg) d.productImg = docData.productImg;
    d.specs = mergeCustom(d.specs || [], docData.custom || []);
  }
  return d;
}

/* Default sales-sheet editorial doc — the blank template the ACC Fichas editor
 * seeds from and a saved product_sheets `data` (kind='sales') overlays onto.
 * Verbatim from the ACC inline helper (was index.html blankEditorial). */
export function blankEditorial() {
  return {
    headline: '', headlineEm: '', subhead: '',
    featuresEyebrow: 'Por qué se vende', featuresTitle: '', featuresTitleEm: '', featuresAside: '',
    features: [], stats: [], bar: [],
    pitchEyebrow: 'El argumento', pitchHeadline: '', pitchHeadlineEm: '', pitchBody: '', pitchSignoff: '',
    boxTitle: '', box: [], brandMode: 'extended', lifestyleImg: '', seriesLogo: '',
  };
}

/* Apply a saved sales doc's editorial layer (flat `ed` shape — the product_sheets
 * `data` jsonb) onto a canonical object from productToSheetData. Returns a new
 * object: maps the flat editorial fields into d.editorial (+ d.meta.brandMode) so
 * renderSalesSheet consumes them. The per-dealer PRICE stays live in d.price (set
 * by the adapter via RLS) and is NEVER part of the doc. Verbatim relocation of the
 * ACC inline withEditorial helper, with `ed` derived from docData here so both ACC
 * and the catalog render the same sheet. */
export function applySalesDoc(data, docData) {
  if (!data) return data;
  var ed = Object.assign(blankEditorial(), docData || {});
  var d = Object.assign({}, data);
  d.meta = Object.assign({}, data.meta, { brandMode: ed.brandMode || 'extended' });
  d.editorial = Object.assign({}, data.editorial, {
    headline: ed.headline, headlineEm: ed.headlineEm, subhead: ed.subhead,
    featuresEyebrow: ed.featuresEyebrow, featuresTitle: ed.featuresTitle, featuresTitleEm: ed.featuresTitleEm, featuresAside: ed.featuresAside,
    features: ed.features, stats: ed.stats, bar: ed.bar,
    pitch: { eyebrow: ed.pitchEyebrow, headline: ed.pitchHeadline, headlineEm: ed.pitchHeadlineEm, body: ed.pitchBody, signoff: ed.pitchSignoff },
    boxTitle: ed.boxTitle, box: ed.box,
    lifestyleImg: ed.lifestyleImg, seriesLogo: ed.seriesLogo,
  });
  return d;
}

/* ===================== canonical -> generator `state` ===================== */
function nz(v) { return v == null ? '' : String(v); }

/* Normalize the DB brand ('HOTLINE'/'RCA'/'WESTINGHOUSE', any case) to the
 * lowercase key each render expects. Without this everything fell back to RCA:
 * BRAND_DEFAULTS_* keys + the CSS data-brand / .brand-* selectors are lowercase,
 * so an uppercase brand missed both the logo/defaults lookup AND the CSS accent.
 * variant 'sales' maps Hotline to a hotline-* key (BRAND_DEFAULTS_SALES has no
 * bare 'hotline'); audio division -> 'hotline-audio'. Unknown brand -> 'rca'. */
function normBrand(raw, variant) {
  var b = String(raw == null ? '' : raw).trim().toLowerCase();
  if (b.indexOf('westinghouse') >= 0) return 'westinghouse';
  if (b.indexOf('hotline') >= 0) return variant === 'sales' ? 'hotline-audio' : 'hotline';
  if (b.indexOf('rca') >= 0) return 'rca';
  if (variant === 'sales') return BRAND_DEFAULTS_SALES[b] ? b : 'rca';
  return BRAND_DEFAULTS_SPEC[b] ? b : 'rca';
}

/* Spec generator state: specs groups use { items:[{label,value}] }. */
function specStateFromCanonical(data) {
  var d = data || {};
  var pk = d.packaging || {};
  var u = pk.unit || {}, i = pk.inner || {}, m = pk.master || {};
  var meta = d.meta || {};
  var productName = d.name || '';
  if (d.nameEn) productName = (d.name ? d.name + ' / ' : '') + d.nameEn;
  return {
    brand: normBrand(d.brand, 'spec'),
    seriesName: d.series || '',
    model: d.model || d.sku || '',
    category: d.category || '',
    productImg: d.productImg || '',
    brandLogo: d.brandLogo || '',
    // drop empty rows (no label AND no value) + groups left with no rows
    specs: (d.specs || []).map(function (g) {
      return { title: g.title || '', items: (g.rows || [])
        .filter(function (r) { return (r.label && String(r.label).trim()) || (r.value && String(r.value).trim()); })
        .map(function (r) { return { label: r.label || '', value: r.value || '' }; }) };
    }).filter(function (g) { return g.items.length > 0; }),
    productName: productName,
    barcode: d.barcode || '',
    hsCode: d.hsCode || '',
    // No hardcoded defaults: absent origin/warranty omit gracefully (Prompt 3b).
    // The DB column DEFAULTs ('China' / '12 meses…') apply to rows that exist.
    countryOfOrigin: d.countryOfOrigin || '',
    unitDimL: nz(u.L), unitDimW: nz(u.W), unitDimH: nz(u.H),
    unitWeight: nz(u.weight), unitColor: u.color || '', unitMaterial: u.material || '',
    innerDimL: nz(i.L), innerDimW: nz(i.W), innerDimH: nz(i.H),
    innerWeight: nz(i.weight), innerUnits: nz(i.units),
    masterDimL: nz(m.L), masterDimW: nz(m.W), masterDimH: nz(m.H),
    masterWeight: nz(m.weight), masterUnits: nz(m.units), masterType: m.type || '',
    moq: d.moq != null ? String(d.moq) : '',
    leadTime: d.leadTime || '',
    fobOrigin: '', // spec sheet never shows FOB/price (internal cost) — kept empty
    warranty: d.warranty || '',
    docType: meta.docType || 'Spec Sheet',
    docYear: meta.docYear || '2026',
    docRev: meta.docRev || '',
    companyName: meta.companyName || 'Latin Trading Co.',
    trademark: meta.trademark || '',
    pageSize: meta.pageSize || 'letter',
    overflowCheck: false
  };
}

/* Sales generator state: specs groups use { rows:[{key,value}] }. */
function salesStateFromCanonical(data) {
  var d = data || {};
  var e = d.editorial || {};
  var p = e.pitch || {};
  var price = d.price || {};
  var meta = d.meta || {};
  return {
    brand: normBrand(d.brand, 'sales'),
    brandMode: meta.brandMode || 'extended',
    seriesName: d.series || '',
    model: d.model || d.sku || '',
    category: d.category || '',
    headline: e.headline || '',
    headlineEm: e.headlineEm || '',
    subhead: e.subhead || '',
    productImg: d.productImg || '',
    lifestyleImg: e.lifestyleImg || '',
    seriesLogo: e.seriesLogo || '',
    brandLogo: d.brandLogo || '',
    stats: e.stats || [],
    bar: e.bar || [],
    featuresEyebrow: e.featuresEyebrow != null ? e.featuresEyebrow : 'Por qué se vende',
    featuresTitle: e.featuresTitle || '',
    featuresTitleEm: e.featuresTitleEm || '',
    featuresAside: e.featuresAside || '',
    features: e.features || [],
    specs: (d.specs || []).map(function (g) {
      return { title: g.title || '', rows: (g.rows || []).map(function (r) {
        return { key: r.label || '', value: r.value || '' };
      }) };
    }),
    pitchEyebrow: p.eyebrow != null ? p.eyebrow : 'El argumento',
    pitchHeadline: p.headline || '',
    pitchHeadlineEm: p.headlineEm || '',
    pitchBody: p.body || '',
    pitchSignoff: p.signoff || '',
    boxTitle: e.boxTitle || '',
    box: e.box || [],
    showPrice: e.showPrice != null ? e.showPrice : true,
    priceLabel: e.priceLabel || 'Mayoreo',
    currency: price.currency || 'USD',
    priceValue: price.amount != null ? String(price.amount) : '',
    fobOrigin: e.fobOrigin || '',
    moq: d.moq != null ? String(d.moq) : '',
    leadTime: d.leadTime || '',
    docType: meta.docType || 'Sales Sheet',
    docYear: meta.docYear || '2026',
    docRev: meta.docRev || '',
    docAudience: meta.docAudience || 'Canal B2B',
    companyName: meta.companyName || '',
    trademark: meta.trademark || '',
    pageSize: meta.pageSize || 'letter',
    overflowCheck: false
  };
}


/* ===================== renderSpecSheet (verbatim body) ===================== */
export function renderSpecSheet(data) {
  var state = specStateFromCanonical(data);
  var brand = state.brand;
  var defaults = BRAND_DEFAULTS_SPEC[brand] || BRAND_DEFAULTS_SPEC.rca;
  // Brand logo: user upload > built-in default > text placeholder
  var brandDefaultLogo = defaults.logoKey ? BRAND_LOGOS[defaults.logoKey] : null;
  var logoSrc = state.brandLogo || brandDefaultLogo;
  var logoBlock = logoSrc
    ? ('<div class="ss-topbar-logo-img"><img src="' + logoSrc + '" alt="' + brand + '" /></div>')
    : ('<div class="ss-topbar-logo ' + (defaults.logoClass || '') + '">' + defaults.logoText + '</div>');

  // === TOPBAR ===
  var seriesPart = state.seriesName ? (' <span class="sep">\u00B7</span> Serie ' + esc(state.seriesName)) : '';
  var catPart = state.category ? (' <span class="sep">\u00B7</span> ' + esc(state.category)) : '';
  var topBar = ''
    + '<header class="ss-topbar">'
    +   logoBlock
    +   '<div class="ss-topbar-id">'
    +     '<div class="ss-breadcrumb">' + esc(brand.toUpperCase().replace(/-/g, ' \u00B7 ')) + seriesPart + catPart + '</div>'
    +     '<div class="ss-model">' + esc(state.model || 'MODELO') + '</div>'
    +   '</div>'
    +   '<div class="ss-topbar-meta">'
    +     '<div class="ss-doctype">' + esc(state.docType || 'Spec Sheet') + '</div>'
    +     '<div>Ficha T\u00E9cnica</div>'
    +     '<div>' + (state.docRev ? esc(state.docRev) + ' \u00B7 ' : '') + esc(state.docYear || '') + '</div>'
    +   '</div>'
    + '</header>';

  // === PRODUCT NAME STRIP ===
  var productNameStrip = '';
  if (state.productName) {
    var parts = state.productName.split('/');
    if (parts.length === 2) {
      productNameStrip = ''
        + '<div class="ss-product-name">'
        +   '<span class="es">' + esc(parts[0].trim()) + '</span>'
        +   '<span class="sep">/</span>'
        +   '<span class="en">' + esc(parts[1].trim()) + '</span>'
        + '</div>';
    } else {
      productNameStrip = '<div class="ss-product-name"><span class="es">' + esc(state.productName) + '</span></div>';
    }
  }

  // === IDENTITY COLUMN (left) ===
  var productImageHtml = state.productImg
    ? '<div class="ss-product-image"><img src="' + state.productImg + '" alt="' + esc(state.model || 'Producto') + '" /></div>'
    : '<div class="ss-product-image ss-empty"><span>Imagen de producto</span></div>';

  // Barcode block — JsBarcode renders into the SVG after the DOM exists
  var barcodeBlock = '';
  if (state.barcode) {
    var fmt = detectBarcodeFormat(state.barcode);
    var fmtLabel = fmt === 'EAN13' ? 'EAN-13' : (fmt === 'UPC' ? 'UPC-A' : (fmt === 'EAN8' ? 'EAN-8' : 'CODE128'));
    barcodeBlock = ''
      + '<div class="ss-barcode-block">'
      +   '<div class="ss-barcode-label">' + fmtLabel + ' \u00B7 C\u00F3digo de Barras</div>'
      +   '<svg id="ssBarcodeSvg" class="ss-barcode-svg" data-value="' + esc(state.barcode) + '" data-format="' + fmt + '"></svg>'
      + '</div>';
  }

  // Marca + Modelo always; Origen / HS Code only when present (graceful omission).
  var qfRows = '<div class="row"><dt>Marca / Brand</dt><dd>' + esc(brand.split('-')[0].toUpperCase()) + '</dd></div>';
  if (state.countryOfOrigin) qfRows += '<div class="row"><dt>Origen / Origin</dt><dd>' + esc(state.countryOfOrigin) + '</dd></div>';
  if (state.hsCode) qfRows += '<div class="row"><dt>HS Code</dt><dd>' + esc(state.hsCode) + '</dd></div>';
  qfRows += '<div class="row"><dt>Modelo / Model</dt><dd>' + (state.model ? esc(state.model) : '<span class="muted">\u2014</span>') + '</dd></div>';
  var quickFactsHtml = '<div class="ss-quickfacts">' + qfRows + '</div>';

  var identityCol = ''
    + '<div class="ss-identity">'
    +   productImageHtml
    +   barcodeBlock
    +   quickFactsHtml
    + '</div>';

  // === TECH SPECS COLUMN (right) ===
  var specsHtml = '<div class="ss-specs">';
  if (state.specs && state.specs.length > 0) {
    state.specs.forEach(function(group) {
      var rowsHtml = '';
      if (group.items && group.items.length > 0) {
        group.items.forEach(function(item) {
          rowsHtml += '<div class="ss-spec-row">'
            + '<span class="ss-spec-label">' + esc(item.label || '') + '</span>'
            + '<span class="ss-spec-value">' + esc(item.value || '') + '</span>'
            + '</div>';
        });
      }
      specsHtml += '<div class="ss-spec-group">'
        + '<div class="ss-spec-group-title"><span>' + esc(group.title || 'Grupo') + '</span></div>'
        + '<div class="ss-spec-rows">' + rowsHtml + '</div>'
        + '</div>';
    });
  } else {
    specsHtml += '<div class="ss-spec-empty">Sin especificaciones \u00B7 agrega un grupo en el panel izquierdo</div>';
  }
  specsHtml += '</div>';

  // === MAIN GRID ===
  var mainGrid = '<section class="ss-main">' + identityCol + specsHtml + '</section>';

  // === PACKAGING TABLE ===
  function fmtDim(l, w, h) {
    if (!l && !w && !h) return '<span class="ss-empty-cell">\u2014 \u00D7 \u2014 \u00D7 \u2014</span>';
    return esc(l || '\u2014') + ' \u00D7 ' + esc(w || '\u2014') + ' \u00D7 ' + esc(h || '\u2014');
  }
  function fmtCell(v) {
    return v ? esc(v) : '<span class="ss-empty-cell">\u2014</span>';
  }
  // A tier row renders only if that tier has at least one value; the whole
  // section is omitted when no tier has data (graceful omission, Prompt 3b).
  var pkgRows = '';
  if (state.unitDimL || state.unitDimW || state.unitDimH || state.unitWeight || state.unitMaterial) {
    pkgRows += '<tr>'
      + '<td class="ss-row-label">Unidad <span class="en">Unit</span></td>'
      + '<td>' + fmtDim(state.unitDimL, state.unitDimW, state.unitDimH) + '</td>'
      + '<td>' + fmtCell(state.unitWeight) + '</td>'
      + '<td>1</td>'
      + '<td>' + fmtCell(state.unitMaterial) + '</td>'
      + '</tr>';
  }
  if (state.innerDimL || state.innerDimW || state.innerDimH || state.innerWeight || state.innerUnits) {
    pkgRows += '<tr>'
      + '<td class="ss-row-label">Caja interior <span class="en">Inner pack</span></td>'
      + '<td>' + fmtDim(state.innerDimL, state.innerDimW, state.innerDimH) + '</td>'
      + '<td>' + fmtCell(state.innerWeight) + '</td>'
      + '<td>' + fmtCell(state.innerUnits) + '</td>'
      + '<td><span class="ss-empty-cell">\u2014</span></td>'
      + '</tr>';
  }
  if (state.masterDimL || state.masterDimW || state.masterDimH || state.masterWeight || state.masterUnits || state.masterType) {
    pkgRows += '<tr>'
      + '<td class="ss-row-label">Caja m\u00E1ster <span class="en">Master carton</span></td>'
      + '<td>' + fmtDim(state.masterDimL, state.masterDimW, state.masterDimH) + '</td>'
      + '<td>' + fmtCell(state.masterWeight) + '</td>'
      + '<td>' + fmtCell(state.masterUnits) + '</td>'
      + '<td>' + fmtCell(state.masterType) + '</td>'
      + '</tr>';
  }
  var packagingHtml = pkgRows
    ? ('<section class="ss-packaging">'
        + '<div class="ss-section-head"><span>Empaque</span><span class="en">Packaging</span></div>'
        + '<table>'
        +   '<thead><tr>'
        +     '<th>Nivel / Level</th>'
        +     '<th>Dimensiones (mm) / Dimensions</th>'
        +     '<th>Peso (kg) / Weight</th>'
        +     '<th>Unidades / Units</th>'
        +     '<th>Tipo / Type</th>'
        +   '</tr></thead>'
        +   '<tbody>' + pkgRows + '</tbody>'
        + '</table>'
      + '</section>')
    : '';

  // === COMMERCIAL STRIP (cells omitted when empty; strip omitted if all empty) ===
  var commCells = [];
  if (state.moq) commCells.push('<div class="cell"><dt>MOQ</dt><dd>' + esc(state.moq) + '</dd></div>');
  if (state.leadTime) commCells.push('<div class="cell"><dt>Lead Time</dt><dd>' + esc(state.leadTime) + '</dd></div>');
  // NO price/cost on the spec sheet \u2014 FOB intentionally omitted (it's internal cost).
  if (state.warranty) commCells.push('<div class="cell"><dt>Garant\u00EDa / Warranty</dt><dd>' + esc(state.warranty) + '</dd></div>');
  var commercialHtml = commCells.length
    ? ('<section class="ss-commercial" style="grid-template-columns:repeat(' + commCells.length + ',1fr)">' + commCells.join('') + '</section>')
    : '';

  // === FOOTER ===
  var footerHtml = ''
    + '<footer class="ss-footer">'
    +   '<div class="ss-footer-left">' + esc(state.companyName || 'Latin Trading Co.') + '</div>'
    +   '<div class="ss-footer-right">'
    +     '<strong>Trademark.</strong> ' + esc(state.trademark || (defaults.trademark || ''))
    +     ' Specifications subject to change without notice.'
    +     (state.docRev ? ' <strong>Doc ' + esc(state.docRev) + ' \u00B7 ' + esc(state.docYear || '') + '</strong>' : '')
    +   '</div>'
    + '</footer>';

  // === ASSEMBLE PAGE ===
  var pageSizeClass = state.pageSize === 'a4' ? 'page-a4' : (state.pageSize === 'legal' ? 'page-legal' : 'page-letter');
  var pageHtml = ''
    + '<div class="ss-page ' + pageSizeClass + '" id="ssPage" data-brand="' + brand + '">'
    +   topBar
    +   productNameStrip
    +   mainGrid
    +   packagingHtml
    +   commercialHtml
    +   footerHtml
    + '</div>';
  return '<div class="lt-sheet lt-spec-sheet">' + pageHtml + '</div>';
}


/* ===================== renderSalesSheet (verbatim body) ===================== */
export function renderSalesSheet(data) {
  var state = salesStateFromCanonical(data);
  var brand = state.brand;
  var defaults = BRAND_DEFAULTS_SALES[brand] || BRAND_DEFAULTS_SALES.rca;
  var currencySymbol = CURRENCY_SYMBOLS[state.currency] || '$';
  var isExtended = state.brandMode === 'extended';
  var isStrict = state.brandMode === 'strict';

  var priceBlock;
  if (state.showPrice && state.priceValue) {
    var fobLine = '';
    if (state.fobOrigin) {
      var curSuffix = state.currency !== 'USD' ? (' \u00B7 ' + state.currency) : ' \u00B7 USD';
      fobLine = '<div class="price-fob">' + esc(state.fobOrigin) + curSuffix + '</div>';
    }
    priceBlock = ''
      + '<div class="p-price-block">'
      + '<div class="price-label">' + esc(state.priceLabel) + '</div>'
      + '<div class="price-value"><span class="currency">' + currencySymbol + '</span>' + esc(state.priceValue) + '</div>'
      + fobLine
      + '</div>';
  } else {
    var skuTag = state.model ? ('<div class="p-sku-tag">SKU \u00B7 ' + esc(state.model) + '</div>') : '';
    priceBlock = ''
      + '<div class="p-price-block">'
      + '<div class="docmeta">' + esc(state.docYear) + ' \u00B7 ' + esc(state.docAudience) + '</div>'
      + skuTag
      + '</div>';
  }

  // Priority: user upload > built-in brand logo > text placeholder
  var brandDefaultLogo = defaults.logoKey ? BRAND_LOGOS[defaults.logoKey] : null;
  var logoSrc = state.brandLogo || brandDefaultLogo;
  var logoBlock = logoSrc
    ? ('<div class="p-logo-img"><img src="' + logoSrc + '" alt="' + brand + '" /></div>')
    : ('<div class="p-logo ' + (defaults.logoClass || '') + '">' + defaults.logoText + '</div>');

  var seriesKicker = state.seriesName ? (' \u00B7 Serie ' + esc(state.seriesName)) : '';
  var topBar = ''
    + '<header class="p-topbar">'
    + '<div class="p-topbar-left">'
    + logoBlock
    + '<div class="p-topbar-meta">'
    + '<div class="kicker">' + esc(state.category || 'Producto de Audio') + seriesKicker + '</div>'
    + '<div class="title">' + esc(state.model || 'Modelo') + ' \u00B7 ' + esc(state.docType) + '</div>'
    + '</div>'
    + '</div>'
    + priceBlock
    + '</header>';

  var heroIsPhoto = isExtended && state.lifestyleImg;
  var heroClasses = ['p-hero'];
  if (isStrict) heroClasses.push('strict-hero');
  if (brand === 'westinghouse' && !heroIsPhoto && !isStrict) heroClasses.push('westinghouse-style');

  var heroBg = heroIsPhoto ? ('<div class="p-hero-bg has-accent" style="background-image:url(' + state.lifestyleImg + ');"></div>') : '';

  var seriesStamp = '';
  if (isExtended && state.seriesLogo) {
    seriesStamp = '<div class="series-stamp"><img src="' + state.seriesLogo + '" alt="' + esc(state.seriesName || 'Serie') + '" /></div>';
  }

  var stats = '';
  state.stats.forEach(function(s, i) {
    if (i > 0) stats += '<div class="p-stat-divider"></div>';
    stats += ''
      + '<div class="p-stat">'
      + '<div class="v">' + escAllowSmall(s.value) + '</div>'
      + '<div class="l">' + esc(s.label) + '</div>'
      + '</div>';
  });

  var productImg = state.productImg
    ? ('<img src="' + state.productImg + '" alt="' + esc(state.model) + '" />')
    : '<div class="placeholder">Sube una imagen de producto</div>';

  var heroEyebrow = '';
  if (isExtended && (state.seriesName || state.category)) {
    var eyText = state.seriesName ? ('Nueva \u00B7 ' + state.seriesName) : state.category;
    heroEyebrow = '<div class="p-hero-eyebrow"><span class="dot"></span>' + esc(eyText) + '</div>';
  } else if (isStrict && state.category) {
    heroEyebrow = '<div class="p-hero-eyebrow strict"><span class="dot"></span>' + esc(state.category) + '</div>';
  }

  var h1Classes = '';
  if (isExtended && brand === 'rca') h1Classes += 'gradient ';
  if (isStrict) h1Classes += 'strict';
  var h1Em = state.headlineEm ? ('<em>' + esc(state.headlineEm) + '</em>') : '';
  var heroSub = state.subhead ? ('<p class="p-hero-sub">' + esc(state.subhead) + '</p>') : '';
  var heroStatsBlock = stats ? ('<div class="p-hero-stats">' + stats + '</div>') : '';

  var heroHtml = ''
    + '<section class="' + heroClasses.join(' ') + '">'
    + heroBg
    + seriesStamp
    + '<div class="p-hero-grid">'
    + '<div class="p-hero-copy">'
    + '<div>'
    + heroEyebrow
    + '<h1 class="' + h1Classes + '">' + esc(state.headline) + ' ' + h1Em + '</h1>'
    + heroSub
    + '</div>'
    + heroStatsBlock
    + '</div>'
    + '<div class="p-hero-product">'
    + '<div class="glow"></div>'
    + productImg
    + '</div>'
    + '</div>'
    + '</section>';

  var featureBar = '';
  if (state.bar.length) {
    var cols = Math.min(state.bar.length, 6);
    var bars = '';
    state.bar.forEach(function(b) {
      bars += ''
        + '<div class="f">'
        + '<div class="lab">' + esc(b.label) + '</div>'
        + '<div class="val">' + esc(b.value) + '</div>'
        + '</div>';
    });
    featureBar = '<div class="p-featurebar" style="--feat-bar-cols:' + cols + ';">' + bars + '</div>';
  }

  var featuresSection = '';
  if (state.features.length || state.featuresTitle) {
    var head = '';
    if (state.featuresEyebrow || state.featuresTitle) {
      var ey = state.featuresEyebrow ? ('<div class="p-section-eyebrow">' + esc(state.featuresEyebrow) + '</div>') : '';
      var titleEm = state.featuresTitleEm ? (' <strong>' + esc(state.featuresTitleEm) + '</strong>') : '';
      var title = state.featuresTitle ? ('<h2 class="p-section-title">' + esc(state.featuresTitle) + titleEm + '</h2>') : '';
      var aside = state.featuresAside ? ('<p class="p-section-aside">' + esc(state.featuresAside) + '</p>') : '';
      head = '<div class="p-section-head"><div>' + ey + title + '</div>' + aside + '</div>';
    }
    var cards = '';
    if (state.features.length) {
      state.features.forEach(function(f) {
        var num = f.num ? ('<div class="num">' + esc(f.num) + '</div>') : '';
        var tt = f.title ? ('<h3>' + esc(f.title) + '</h3>') : '';
        var desc = f.desc ? ('<p>' + esc(f.desc) + '</p>') : '';
        cards += '<div class="p-feat">' + num + tt + desc + '</div>';
      });
      cards = '<div class="p-features">' + cards + '</div>';
    }
    featuresSection = '<section class="p-section">' + head + cards + '</section>';
  }

  var specsSection = '';
  var validSpecs = state.specs.filter(function(g) {
    return g.title || (g.rows && g.rows.some(function(r) { return r.key || r.value; }));
  });
  if (validSpecs.length) {
    var groups = '';
    validSpecs.forEach(function(g) {
      var h4 = g.title ? ('<h4>' + esc(g.title) + '</h4>') : '';
      var rows = '';
      (g.rows || []).filter(function(r) { return r.key || r.value; }).forEach(function(r) {
        rows += '<dt>' + esc(r.key) + '</dt><dd>' + esc(r.value) + '</dd>';
      });
      groups += '<div class="p-spec-group">' + h4 + '<dl>' + rows + '</dl></div>';
    });
    specsSection = ''
      + '<section class="p-section" style="padding-top:0;">'
      + '<div class="p-section-head"><div>'
      + '<div class="p-section-eyebrow">Especificaciones</div>'
      + '<h2 class="p-section-title">Los datos <strong>técnicos.</strong></h2>'
      + '</div></div>'
      + '<div class="p-specs">' + groups + '</div>'
      + '</section>';
  }

  var splitSection = '';
  if (state.pitchHeadline || state.box.length) {
    var signoff = state.pitchSignoff || defaults.signoff;
    var pitch = '<div></div>';
    if (state.pitchHeadline || state.pitchBody) {
      var pey = state.pitchEyebrow ? ('<div class="p-section-eyebrow">' + esc(state.pitchEyebrow) + '</div>') : '';
      var pheadEm = state.pitchHeadlineEm ? (' <strong>' + esc(state.pitchHeadlineEm) + '</strong>') : '';
      var phead = state.pitchHeadline ? ('<h3>' + esc(state.pitchHeadline) + pheadEm + '</h3>') : '';
      var pbody = state.pitchBody ? ('<p>' + esc(state.pitchBody) + '</p>') : '';
      var sign = signoff ? ('<div class="signoff">' + signoff + '</div>') : '';
      pitch = '<div class="p-pitch">' + pey + phead + pbody + sign + '</div>';
    }
    var box = '';
    if (state.box.length) {
      var boxTitle = state.boxTitle ? ('<h3 style="font-size:13px;">' + esc(state.boxTitle) + '</h3>') : '';
      var items = '';
      state.box.filter(function(b) { return b.item; }).forEach(function(b, i) {
        var num = String(i + 1);
        if (num.length < 2) num = '0' + num;
        items += ''
          + '<li>'
          + '<span class="num">' + num + '</span>'
          + '<span>' + esc(b.item) + '</span>'
          + '<span class="qty">' + esc(b.qty) + '</span>'
          + '</li>';
      });
      box = '<div class="p-box">' + boxTitle + '<ul class="p-box-list">' + items + '</ul></div>';
    }
    splitSection = '<section class="p-section" style="padding-top:0;"><div class="p-split">' + pitch + box + '</div></section>';
  }

  var footerLeft = state.trademark || defaults.trademark;
  var footerRev = state.docRev ? (' \u00B7 ' + esc(state.docRev)) : '';
  var footer = ''
    + '<footer class="p-footer">'
    + '<div>' + esc(footerLeft) + footerRev + '</div>'
    + '<div class="made">' + defaults.footerMade + '</div>'
    + '</footer>';

  var sizeClass = state.pageSize === 'a4' ? 'a4' : '';
  var pageCls = 'brand-' + brand + (sizeClass ? (' ' + sizeClass) : '');
  var pageHtml = '<div class="page ' + pageCls + '">'
    + topBar + heroHtml + featureBar + featuresSection + specsSection + splitSection + footer
    + '</div>';
  return '<div class="lt-sheet lt-sales-sheet">' + pageHtml + '</div>';
}


/* ===================== styles (verbatim rules, scoped by CSS nesting) ===================== */
var SHEET_CSS = "@import url(\"https://fonts.googleapis.com/css2?family=Mulish:wght@200;300;400;500;600;700;800;900&family=Barlow+Condensed:wght@400;500;600;700;800;900&family=Inter:wght@300;400;500;600;700&display=swap\");\n.lt-spec-sheet {\n/* ============ SPEC SHEET RENDERED PREVIEW STYLES ============\n   \"Audit report\" aesthetic \u2014 dense, official, no marketing.\n   Same brand color tokens as sales sheet so brand engine works.\n   Class prefix: ss-  (spec sheet) \u2014 avoids collision with old .p-* */\n\n.ss-page {\n  width: 8.5in;\n  min-height: 11in;\n  margin: 0 auto;\n  background: #fff;\n  padding: 0.45in 0.5in;\n  font-family: 'Mulish', system-ui, sans-serif;\n  color: #222;\n  font-size: 9.5px;\n  line-height: 1.35;\n  box-shadow: 0 4px 24px rgba(0,0,0,0.08);\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n.ss-page.page-a4 { width: 210mm; min-height: 297mm; }\n.ss-page.page-legal { width: 8.5in; min-height: 14in; }\n\n/* Brand-specific accents \u2014 reuse same primary tokens */\n.ss-page[data-brand=\"rca\"] { --ss-accent: #D50032; }\n.ss-page[data-brand=\"westinghouse\"] { --ss-accent: #295BDD; }\n.ss-page[data-brand^=\"hotline\"] { --ss-accent: #1E78C7; }\n\n.ss-page {\n  --ss-accent: #D50032;\n  --ss-border: #c8c9cb;\n  --ss-border-strong: #3a3a3a;\n  --ss-light: #f5f5f6;\n  --ss-light-2: #fafafb;\n  --ss-text-soft: #6b6b6b;\n}\n\n/* --- Top bar --- */\n.ss-topbar {\n  display: grid;\n  grid-template-columns: auto 1fr auto;\n  align-items: center;\n  gap: 16px;\n  padding-bottom: 9px;\n  border-bottom: 2px solid var(--ss-border-strong);\n}\n.ss-topbar-logo {\n  height: 36px;\n  width: 36px;\n  background: var(--ss-accent);\n  color: #fff;\n  font-weight: 800;\n  font-size: 12px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  letter-spacing: 0.5px;\n}\n.ss-topbar-logo-img {\n  height: 36px;\n  display: flex;\n  align-items: center;\n}\n.ss-topbar-logo-img img {\n  height: 36px;\n  width: auto;\n  display: block;\n  object-fit: contain;\n}\n.ss-topbar-id { display: flex; flex-direction: column; gap: 2px; min-width: 0; }\n.ss-topbar-id .ss-model {\n  font-family: 'Barlow Condensed', system-ui, sans-serif;\n  font-weight: 800;\n  font-size: 22px;\n  line-height: 1;\n  letter-spacing: 0.2px;\n  text-transform: uppercase;\n  color: #222;\n}\n.ss-topbar-id .ss-breadcrumb {\n  font-size: 8.5px;\n  color: var(--ss-text-soft);\n  text-transform: uppercase;\n  letter-spacing: 0.8px;\n  font-weight: 600;\n}\n.ss-topbar-id .ss-breadcrumb .sep { margin: 0 6px; color: var(--ss-border); }\n.ss-topbar-meta {\n  text-align: right;\n  font-size: 8px;\n  line-height: 1.5;\n  color: var(--ss-text-soft);\n  text-transform: uppercase;\n  letter-spacing: 0.6px;\n}\n.ss-topbar-meta .ss-doctype {\n  font-family: 'Barlow Condensed', system-ui, sans-serif;\n  font-weight: 700;\n  font-size: 11px;\n  color: #222;\n  letter-spacing: 0.5px;\n  margin-bottom: 2px;\n}\n\n/* --- Product name strip --- */\n.ss-product-name {\n  font-family: 'Barlow Condensed', system-ui, sans-serif;\n  font-weight: 600;\n  font-size: 12px;\n  line-height: 1.3;\n  color: #222;\n  padding: 4px 0 0;\n}\n.ss-product-name .es { color: #222; }\n.ss-product-name .sep { color: var(--ss-border); margin: 0 8px; }\n.ss-product-name .en { color: var(--ss-text-soft); font-style: italic; }\n\n/* --- Main grid --- */\n.ss-main {\n  display: grid;\n  grid-template-columns: 2.55in 1fr;\n  gap: 14px;\n}\n.ss-identity { display: flex; flex-direction: column; gap: 10px; }\n.ss-product-image {\n  width: 100%;\n  aspect-ratio: 1 / 1;\n  background: var(--ss-light);\n  border: 1px solid var(--ss-border);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  overflow: hidden;\n}\n.ss-product-image img {\n  max-width: 90%;\n  max-height: 90%;\n  object-fit: contain;\n}\n.ss-product-image.ss-empty span {\n  color: var(--ss-text-soft);\n  font-size: 8.5px;\n  text-transform: uppercase;\n  letter-spacing: 1px;\n  font-weight: 600;\n}\n\n/* --- Barcode block --- */\n.ss-barcode-block {\n  border: 1px solid var(--ss-border);\n  padding: 10px 8px 8px;\n  text-align: center;\n}\n.ss-barcode-label {\n  font-size: 7px;\n  text-transform: uppercase;\n  letter-spacing: 1px;\n  color: var(--ss-text-soft);\n  font-weight: 700;\n  margin-bottom: 6px;\n}\n.ss-barcode-svg {\n  display: block;\n  width: 100%;\n  height: auto;\n  max-height: 60px;\n}\n.ss-barcode-error {\n  padding: 10px 8px;\n  background: #fff5f5;\n  border: 1px dashed #d97070;\n  color: #a02020;\n  font-size: 8px;\n  text-align: center;\n  line-height: 1.4;\n  border-radius: 3px;\n}\n.ss-barcode-error .hint {\n  color: #8a4a4a;\n  font-size: 7px;\n  font-style: italic;\n}\n\n/* --- Quick facts --- */\n.ss-quickfacts {\n  border: 1px solid var(--ss-border);\n  border-top: 2px solid var(--ss-border-strong);\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n}\n.ss-quickfacts .row {\n  padding: 6px 8px;\n  border-bottom: 1px solid var(--ss-border);\n  border-right: 1px solid var(--ss-border);\n}\n.ss-quickfacts .row:nth-child(2n) { border-right: none; }\n.ss-quickfacts .row:nth-last-child(-n+2) { border-bottom: none; }\n.ss-quickfacts dt {\n  font-size: 7px;\n  text-transform: uppercase;\n  letter-spacing: 0.8px;\n  color: var(--ss-text-soft);\n  font-weight: 700;\n  margin-bottom: 2px;\n}\n.ss-quickfacts dd {\n  font-family: 'Barlow Condensed', system-ui, sans-serif;\n  font-size: 13px;\n  font-weight: 700;\n  color: #222;\n  line-height: 1.1;\n}\n.ss-quickfacts dd .muted { color: var(--ss-border); font-weight: 500; }\n\n/* --- Specs column --- */\n.ss-specs {\n  border-top: 2px solid var(--ss-border-strong);\n  border-bottom: 1px solid var(--ss-border);\n}\n.ss-spec-empty {\n  padding: 20px;\n  text-align: center;\n  font-size: 9px;\n  color: var(--ss-text-soft);\n  font-style: italic;\n}\n.ss-spec-group { border-bottom: 1px solid var(--ss-border); }\n.ss-spec-group:last-child { border-bottom: none; }\n.ss-spec-group-title {\n  background: var(--ss-light);\n  padding: 4px 8px;\n  font-size: 8px;\n  text-transform: uppercase;\n  letter-spacing: 1.2px;\n  color: #222;\n  font-weight: 800;\n  border-bottom: 1px solid var(--ss-border);\n}\n.ss-spec-rows {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n}\n.ss-spec-row {\n  display: grid;\n  grid-template-columns: 1.1fr 1fr;\n  padding: 4px 8px;\n  gap: 6px;\n  border-right: 1px solid var(--ss-border);\n  align-items: baseline;\n  min-height: 22px;\n}\n.ss-spec-row:nth-child(2n) { border-right: none; }\n.ss-spec-row:nth-child(n+3) { border-top: 1px solid var(--ss-border); }\n.ss-spec-label {\n  font-size: 8.5px;\n  color: var(--ss-text-soft);\n  text-transform: uppercase;\n  letter-spacing: 0.4px;\n  font-weight: 600;\n}\n.ss-spec-value {\n  font-size: 9.5px;\n  color: #222;\n  font-weight: 600;\n}\n\n/* --- Packaging table --- */\n.ss-packaging {\n  border: 1px solid var(--ss-border);\n  border-top: 2px solid var(--ss-border-strong);\n}\n.ss-section-head {\n  background: var(--ss-light);\n  padding: 4px 8px;\n  font-size: 8px;\n  text-transform: uppercase;\n  letter-spacing: 1.2px;\n  color: #222;\n  font-weight: 800;\n  display: flex;\n  justify-content: space-between;\n  align-items: baseline;\n  border-bottom: 1px solid var(--ss-border);\n}\n.ss-section-head .en {\n  color: var(--ss-text-soft);\n  font-style: italic;\n  font-weight: 600;\n  letter-spacing: 0.5px;\n  text-transform: none;\n}\n.ss-packaging table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 9px;\n}\n.ss-packaging th, .ss-packaging td {\n  padding: 5px 8px;\n  border-bottom: 1px solid var(--ss-border);\n  border-right: 1px solid var(--ss-border);\n  text-align: left;\n  vertical-align: middle;\n}\n.ss-packaging th:last-child, .ss-packaging td:last-child { border-right: none; }\n.ss-packaging tr:last-child td { border-bottom: none; }\n.ss-packaging th {\n  font-size: 7.5px;\n  text-transform: uppercase;\n  letter-spacing: 0.8px;\n  color: var(--ss-text-soft);\n  font-weight: 700;\n  background: var(--ss-light-2);\n}\n.ss-packaging td {\n  font-feature-settings: 'tnum';\n  font-weight: 600;\n}\n.ss-row-label {\n  font-family: 'Barlow Condensed', system-ui, sans-serif;\n  font-weight: 700;\n  font-size: 11px;\n  text-transform: uppercase;\n  letter-spacing: 0.4px;\n  color: #222;\n  width: 1.4in;\n}\n.ss-row-label .en {\n  display: block;\n  font-family: 'Mulish', system-ui, sans-serif;\n  font-size: 7px;\n  font-weight: 500;\n  color: var(--ss-text-soft);\n  text-transform: none;\n  letter-spacing: 0.2px;\n  font-style: italic;\n  margin-top: 1px;\n}\n.ss-empty-cell { color: var(--ss-border); font-weight: 400; }\n\n/* --- Commercial strip --- */\n.ss-commercial {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  border: 1px solid var(--ss-border);\n  border-top: 2px solid var(--ss-border-strong);\n}\n.ss-commercial .cell {\n  padding: 6px 8px;\n  border-right: 1px solid var(--ss-border);\n}\n.ss-commercial .cell:last-child { border-right: none; }\n.ss-commercial dt {\n  font-size: 7px;\n  text-transform: uppercase;\n  letter-spacing: 0.8px;\n  color: var(--ss-text-soft);\n  font-weight: 700;\n  margin-bottom: 2px;\n}\n.ss-commercial dd {\n  font-family: 'Barlow Condensed', system-ui, sans-serif;\n  font-size: 13px;\n  font-weight: 700;\n  color: #222;\n  line-height: 1.1;\n}\n.ss-commercial dd .muted { color: var(--ss-border); font-weight: 500; }\n\n/* --- Footer --- */\n.ss-footer {\n  margin-top: auto;\n  padding-top: 9px;\n  border-top: 1px solid var(--ss-border);\n  display: flex;\n  justify-content: space-between;\n  align-items: flex-end;\n  gap: 20px;\n  font-size: 7px;\n  color: var(--ss-text-soft);\n  line-height: 1.5;\n}\n.ss-footer-left {\n  font-family: 'Barlow Condensed', system-ui, sans-serif;\n  font-size: 9px;\n  font-weight: 700;\n  color: #222;\n  text-transform: uppercase;\n  letter-spacing: 0.8px;\n}\n.ss-footer-right { text-align: right; max-width: 4in; }\n.ss-footer-right strong { color: #222; }\n\n/* Print */\n@media print {\n  .ss-page { box-shadow: none; margin: 0; }\n}\n/* ============ END SPEC SHEET STYLES ============ */\n\n}\n.lt-sales-sheet {\n  .page {\n    width: 8.5in;\n    height: 11in;\n    background: #fff;\n    color: #222;\n    box-shadow: 0 8px 40px rgba(0,0,0,0.5);\n    overflow: hidden;\n    position: relative;\n    display: flex;\n    flex-direction: column;\n  }\n  .page.a4 { width: 210mm; height: 297mm; }\n  .page.overflow { box-shadow: 0 8px 40px rgba(255,107,61,0.5), 0 0 0 3px #ff6b3d; }\n\n  /* RCA defaults */\n  .page {\n    --brand-primary: #D50032;\n    --brand-text: #444041;\n    --brand-text-soft: #77787B;\n    --brand-border: #DCDDDE;\n    --brand-light: #F1F1F2;\n    --brand-dark: #2a2628;\n    --brand-display-font: 'Mulish', system-ui, sans-serif;\n    --brand-display-weight-light: 200;\n    --brand-display-weight-bold: 700;\n  }\n  .page.brand-westinghouse {\n    --brand-primary: #295BDD;\n    --brand-text: #1a1a1a;\n    --brand-text-soft: #555;\n    --brand-dark: #25346A;\n    --brand-display-font: 'Barlow Condensed', system-ui, sans-serif;\n    --brand-display-weight-light: 500;\n    --brand-display-weight-bold: 800;\n  }\n  .page.brand-hotline-blanca,\n  .page.brand-hotline-tv,\n  .page.brand-hotline-audio {\n    --brand-primary: #2B3C73;\n    --brand-dark: #231F20;\n  }\n  .page.brand-hotline-cuidado {\n    --brand-primary: #EE212E;\n    --brand-dark: #231F20;\n  }\n\n  .p-topbar {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    padding: 0.18in 0.4in;\n    border-bottom: 1px solid var(--brand-border);\n    background: #fff;\n    flex-shrink: 0;\n  }\n  .p-topbar-left { display: flex; align-items: center; gap: 14px; }\n  .p-logo {\n    background: var(--brand-primary);\n    color: #fff;\n    font-family: var(--brand-display-font);\n    font-weight: 900;\n    font-size: 13px;\n    letter-spacing: 0.04em;\n    width: 36px;\n    height: 36px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    border-radius: 2px;\n  }\n  .p-logo.westinghouse {\n    border-radius: 50%;\n    font-style: italic;\n    font-size: 18px;\n  }\n  .p-logo-img {\n    display: flex;\n    align-items: center;\n    height: 0.4in;\n  }\n  .p-logo-img img {\n    max-height: 0.4in;\n    max-width: 1.4in;\n    width: auto;\n    height: auto;\n    display: block;\n    object-fit: contain;\n  }\n  .p-topbar-meta { line-height: 1.15; }\n  .p-topbar-meta .kicker {\n    font-size: 8.5px;\n    letter-spacing: 0.16em;\n    text-transform: uppercase;\n    color: var(--brand-primary);\n    font-weight: 700;\n  }\n  .p-topbar-meta .title {\n    font-size: 13px;\n    font-weight: 600;\n    color: var(--brand-text);\n    margin-top: 1px;\n  }\n  .p-price-block { display: flex; flex-direction: column; align-items: flex-end; }\n  .p-price-block .price-label {\n    font-size: 8px;\n    letter-spacing: 0.2em;\n    text-transform: uppercase;\n    color: var(--brand-text-soft);\n    font-weight: 600;\n  }\n  .p-price-block .price-value {\n    font-family: var(--brand-display-font);\n    font-size: 22px;\n    font-weight: 700;\n    color: var(--brand-text);\n    line-height: 1;\n    margin-top: 2px;\n  }\n  .p-price-block .price-value .currency {\n    font-size: 13px;\n    color: var(--brand-text-soft);\n    font-weight: 500;\n    margin-right: 2px;\n  }\n  .p-price-block .price-fob {\n    font-size: 8px;\n    letter-spacing: 0.16em;\n    text-transform: uppercase;\n    color: var(--brand-text-soft);\n    margin-top: 2px;\n  }\n  .p-price-block .docmeta {\n    font-size: 8px;\n    letter-spacing: 0.18em;\n    text-transform: uppercase;\n    color: var(--brand-text-soft);\n    font-weight: 600;\n    margin-bottom: 2px;\n  }\n  .p-sku-tag {\n    display: inline-block;\n    color: var(--brand-primary);\n    border: 1px solid var(--brand-primary);\n    padding: 3px 8px;\n    font-size: 8.5px;\n    font-weight: 700;\n    letter-spacing: 0.14em;\n    text-transform: uppercase;\n    margin-top: 4px;\n  }\n\n  .p-hero {\n    position: relative;\n    height: 3.1in;\n    background: var(--brand-dark);\n    color: #fff;\n    overflow: hidden;\n    flex-shrink: 0;\n  }\n  .p-hero-bg {\n    position: absolute;\n    inset: 0;\n    background-size: cover;\n    background-position: center;\n    filter: saturate(1.05) brightness(0.7);\n  }\n  .p-hero-bg::after {\n    content: \"\";\n    position: absolute;\n    inset: 0;\n    background: linear-gradient(180deg, rgba(0,0,0,0.4), rgba(0,0,0,0.2) 40%, rgba(0,0,0,0.85));\n  }\n  .p-hero-bg.has-accent::before {\n    content: \"\";\n    position: absolute;\n    inset: 0;\n    background: radial-gradient(60% 80% at 30% 60%, var(--brand-primary), transparent 60%);\n    opacity: 0.35;\n    mix-blend-mode: screen;\n  }\n  .p-hero-grid {\n    position: relative;\n    z-index: 2;\n    height: 100%;\n    display: grid;\n    grid-template-columns: 1.2fr 1fr;\n    grid-template-rows: 1fr;\n    padding: 0.3in 0.4in 0.26in;\n    gap: 0.2in;\n    min-height: 0;\n  }\n  .p-hero-copy { display: flex; flex-direction: column; justify-content: space-between; }\n  .p-hero-eyebrow {\n    display: inline-flex;\n    align-items: center;\n    gap: 6px;\n    background: var(--brand-primary);\n    color: #fff;\n    font-size: 8px;\n    letter-spacing: 0.22em;\n    text-transform: uppercase;\n    font-weight: 700;\n    padding: 5px 9px;\n    align-self: flex-start;\n  }\n  .p-hero-eyebrow .dot {\n    width: 4px;\n    height: 4px;\n    background: #fff;\n    border-radius: 50%;\n  }\n  .p-hero h1 {\n    font-family: var(--brand-display-font);\n    font-weight: var(--brand-display-weight-light);\n    font-size: 34px;\n    line-height: 0.98;\n    letter-spacing: -0.02em;\n    margin: 10px 0 0;\n    color: #fff;\n    max-width: 9ch;\n  }\n  .p-hero h1 em {\n    font-style: normal;\n    font-weight: var(--brand-display-weight-bold);\n    color: var(--brand-primary);\n    display: block;\n  }\n  .p-hero h1.gradient em {\n    background: linear-gradient(180deg, #ff8a3d 0%, #ff3b8a 50%, #b34dff 100%);\n    -webkit-background-clip: text;\n    background-clip: text;\n    color: transparent;\n  }\n  .p-hero-sub {\n    margin-top: 10px;\n    max-width: 4in;\n    font-size: 11px;\n    line-height: 1.45;\n    font-weight: 300;\n    color: rgba(255,255,255,0.85);\n  }\n  .p-hero-stats {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 14px 24px;\n    align-items: flex-end;\n  }\n  .p-stat { display: flex; flex-direction: column; gap: 2px; }\n  .p-stat .v {\n    font-family: var(--brand-display-font);\n    font-size: 22px;\n    font-weight: 800;\n    line-height: 1;\n    color: #fff;\n  }\n  .p-stat .v small {\n    font-size: 11px;\n    font-weight: 400;\n    color: rgba(255,255,255,0.7);\n    margin-left: 2px;\n  }\n  .p-stat .l {\n    font-size: 7.5px;\n    letter-spacing: 0.16em;\n    text-transform: uppercase;\n    color: rgba(255,255,255,0.65);\n    font-weight: 700;\n  }\n  .p-stat-divider {\n    width: 1px;\n    height: 24px;\n    background: rgba(255,255,255,0.18);\n  }\n  .p-hero-product {\n    position: relative;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    min-height: 0;\n    min-width: 0;\n    overflow: hidden;\n  }\n  .p-hero-product .glow {\n    position: absolute;\n    width: 80%;\n    height: 80%;\n    border-radius: 50%;\n    background: radial-gradient(circle, var(--brand-primary), transparent 70%);\n    filter: blur(20px);\n    opacity: 0.3;\n  }\n  .p-hero-product img {\n    position: relative;\n    z-index: 2;\n    max-width: 100%;\n    max-height: 100%;\n    width: auto;\n    height: auto;\n    object-fit: contain;\n    filter: drop-shadow(0 18px 30px rgba(0,0,0,0.5));\n  }\n  .p-hero-product .placeholder {\n    position: relative;\n    z-index: 2;\n    width: 70%;\n    height: 70%;\n    border: 2px dashed rgba(255,255,255,0.3);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: rgba(255,255,255,0.5);\n    font-size: 11px;\n  }\n\n  /* Modo estricto */\n  .p-hero.strict-hero { background: #fff; color: var(--brand-text); height: 3.1in; }\n  .p-hero.strict-hero .p-hero-bg { display: none; }\n  .p-hero.strict-hero::after {\n    content: \"\";\n    position: absolute;\n    left: 0;\n    top: 0;\n    bottom: 0;\n    width: 55%;\n    background: var(--brand-light);\n    z-index: 0;\n  }\n  .p-hero.strict-hero .p-hero-grid { padding: 0.32in 0.4in; }\n  .p-hero.strict-hero h1.strict {\n    color: var(--brand-text);\n    font-weight: 600;\n    font-size: 30px;\n  }\n  .p-hero.strict-hero h1.strict em { color: var(--brand-primary); font-weight: 700; }\n  .p-hero.strict-hero .p-hero-sub { color: var(--brand-text-soft); }\n  .p-hero.strict-hero .p-stat .v { color: var(--brand-text); }\n  .p-hero.strict-hero .p-stat .v small { color: var(--brand-text-soft); }\n  .p-hero.strict-hero .p-stat .l { color: var(--brand-text-soft); }\n  .p-hero.strict-hero .p-stat-divider { background: var(--brand-border); }\n  .p-hero.strict-hero .p-hero-product .glow {\n    background: radial-gradient(circle, rgba(0,0,0,0.08), transparent 70%);\n    opacity: 1;\n  }\n  .p-hero.strict-hero .p-hero-product img {\n    filter: drop-shadow(0 12px 20px rgba(0,0,0,0.18));\n  }\n  .p-hero.strict-hero .p-hero-product .placeholder {\n    border-color: rgba(0,0,0,0.2);\n    color: rgba(0,0,0,0.4);\n  }\n\n  /* Tratamiento Westinghouse c\u00edrculo */\n  .p-hero.westinghouse-style { background: var(--brand-primary); }\n  .p-hero.westinghouse-style .p-hero-bg { display: none; }\n  .p-hero.westinghouse-style .p-hero-product .glow { display: none; }\n  .p-hero.westinghouse-style .p-hero-product::before {\n    content: \"\";\n    position: absolute;\n    width: 80%;\n    height: 80%;\n    background: #fff;\n    border-radius: 50%;\n    z-index: 1;\n  }\n\n  /* Logo de serie (subido) */\n  .series-stamp {\n    position: absolute;\n    top: 0.2in;\n    right: 0.4in;\n    z-index: 3;\n    pointer-events: none;\n    max-width: 1.6in;\n    max-height: 0.9in;\n  }\n  .series-stamp img {\n    display: block;\n    max-width: 100%;\n    max-height: 0.9in;\n    width: auto;\n    height: auto;\n    filter: drop-shadow(0 4px 12px rgba(0,0,0,0.4));\n  }\n\n  .p-featurebar {\n    display: grid;\n    grid-template-columns: repeat(var(--feat-bar-cols, 4), 1fr);\n    background: var(--brand-dark);\n    color: #fff;\n    flex-shrink: 0;\n  }\n  .p-featurebar .f {\n    padding: 0.12in 0.14in;\n    border-right: 1px solid rgba(255,255,255,0.08);\n    display: flex;\n    flex-direction: column;\n    gap: 1px;\n  }\n  .p-featurebar .f:last-child { border-right: none; }\n  .p-featurebar .f .lab {\n    font-size: 7.5px;\n    letter-spacing: 0.16em;\n    text-transform: uppercase;\n    color: rgba(255,255,255,0.55);\n    font-weight: 700;\n  }\n  .p-featurebar .f .val {\n    font-size: 11px;\n    font-weight: 600;\n    color: #fff;\n    line-height: 1.2;\n  }\n\n  .p-section { padding: 0.18in 0.4in; flex-shrink: 0; }\n  .p-section-head {\n    display: flex;\n    align-items: baseline;\n    justify-content: space-between;\n    margin-bottom: 0.1in;\n    gap: 0.2in;\n  }\n  .p-section-eyebrow {\n    font-size: 8.5px;\n    letter-spacing: 0.2em;\n    text-transform: uppercase;\n    color: var(--brand-primary);\n    font-weight: 700;\n  }\n  .p-section-title {\n    font-family: var(--brand-display-font);\n    font-weight: var(--brand-display-weight-light);\n    font-size: 19px;\n    line-height: 1.05;\n    letter-spacing: -0.02em;\n    color: var(--brand-text);\n    margin: 2px 0 0;\n  }\n  .p-section-title strong {\n    font-weight: var(--brand-display-weight-bold);\n    color: var(--brand-primary);\n  }\n  .p-section-aside {\n    max-width: 2.2in;\n    font-size: 9px;\n    line-height: 1.45;\n    color: var(--brand-text-soft);\n  }\n\n  .p-features {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 0.08in;\n  }\n  .p-feat {\n    border: 1px solid var(--brand-border);\n    padding: 0.12in 0.12in 0.1in;\n    background: #fff;\n    display: flex;\n    flex-direction: column;\n    gap: 3px;\n  }\n  .p-feat .num {\n    font-family: var(--brand-display-font);\n    font-size: 7.5px;\n    font-weight: 700;\n    color: var(--brand-primary);\n    letter-spacing: 0.16em;\n    margin-bottom: 1px;\n  }\n  .p-feat h3 {\n    font-size: 10.5px;\n    font-weight: 700;\n    color: var(--brand-text);\n    margin: 0;\n    line-height: 1.2;\n  }\n  .p-feat p {\n    margin: 0;\n    font-size: 8.5px;\n    line-height: 1.4;\n    color: var(--brand-text-soft);\n  }\n\n  .p-specs {\n    display: grid;\n    grid-template-columns: repeat(3, 1fr);\n    gap: 0 0.24in;\n  }\n  .p-spec-group h4 {\n    font-size: 8.5px;\n    letter-spacing: 0.18em;\n    text-transform: uppercase;\n    font-weight: 700;\n    color: var(--brand-primary);\n    margin: 0 0 5px;\n    padding-bottom: 4px;\n    border-bottom: 1.5px solid var(--brand-dark);\n  }\n  .p-spec-group dl {\n    display: grid;\n    grid-template-columns: 40% 1fr;\n    margin: 0 0 0.1in;\n  }\n  .p-spec-group dt, .p-spec-group dd {\n    padding: 3px 0;\n    font-size: 8.5px;\n    border-bottom: 1px solid var(--brand-border);\n    line-height: 1.3;\n  }\n  .p-spec-group dt { font-weight: 600; color: var(--brand-text); }\n  .p-spec-group dd { margin: 0; color: var(--brand-text-soft); }\n\n  .p-split {\n    display: grid;\n    grid-template-columns: 1.3fr 1fr;\n    gap: 0.2in;\n  }\n  .p-pitch h3, .p-box h3 {\n    font-family: var(--brand-display-font);\n    font-size: 17px;\n    font-weight: var(--brand-display-weight-light);\n    margin: 0 0 6px;\n    color: var(--brand-text);\n    line-height: 1.1;\n  }\n  .p-pitch h3 strong, .p-box h3 strong {\n    font-weight: var(--brand-display-weight-bold);\n    color: var(--brand-primary);\n  }\n  .p-pitch p {\n    font-size: 9.5px;\n    line-height: 1.5;\n    color: var(--brand-text-soft);\n    margin: 0 0 6px;\n  }\n  .p-pitch .signoff {\n    font-size: 8.5px;\n    letter-spacing: 0.18em;\n    text-transform: uppercase;\n    font-weight: 700;\n    color: var(--brand-text);\n    margin-top: 6px;\n  }\n  .p-pitch .signoff strong { color: var(--brand-primary); }\n\n  .p-box {\n    background: var(--brand-light);\n    padding: 0.16in 0.18in;\n  }\n  .p-box-list { list-style: none; padding: 0; margin: 0; }\n  .p-box-list li {\n    display: grid;\n    grid-template-columns: 18px 1fr auto;\n    align-items: center;\n    gap: 6px;\n    font-size: 9px;\n    color: var(--brand-text);\n    padding: 3px 0;\n    border-bottom: 1px solid var(--brand-border);\n  }\n  .p-box-list li:last-child { border-bottom: none; }\n  .p-box-list .num {\n    font-family: var(--brand-display-font);\n    font-size: 7.5px;\n    font-weight: 700;\n    color: var(--brand-primary);\n    letter-spacing: 0.1em;\n  }\n  .p-box-list .qty { color: var(--brand-text-soft); font-size: 8.5px; }\n\n  .p-footer {\n    margin-top: auto;\n    padding: 0.12in 0.4in;\n    background: var(--brand-dark);\n    color: rgba(255,255,255,0.55);\n    font-size: 7.5px;\n    letter-spacing: 0.1em;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    flex-shrink: 0;\n  }\n  .p-footer .made {\n    color: #fff;\n    letter-spacing: 0.2em;\n    text-transform: uppercase;\n    font-weight: 700;\n  }\n  .p-footer .made span { color: var(--brand-primary); }\n\n}\n";

export function injectSheetStyles(doc) {
  doc = doc || (typeof document !== 'undefined' ? document : null);
  if (!doc) return;
  if (doc.getElementById('lt-sheet-styles')) return;
  var st = doc.createElement('style');
  st.id = 'lt-sheet-styles';
  st.textContent = SHEET_CSS;
  (doc.head || doc.documentElement).appendChild(st);
}


/* ===================== barcode hydration ===================== */
/* Call after the spec sheet is in the DOM. JsBarcode v3.12.3 expected (the version the
   spec generator inlined). Options are verbatim from that generator. */
export function hydrateBarcodes(root, JsBarcode) {
  if (!root) return;
  var JB = JsBarcode || (typeof globalThis !== 'undefined' ? globalThis.JsBarcode : undefined);
  var svgs = root.querySelectorAll ? root.querySelectorAll('svg[data-value][data-format]') : [];
  for (var n = 0; n < svgs.length; n++) {
    var el = svgs[n];
    var v = el.getAttribute('data-value');
    var f = el.getAttribute('data-format');
    if (!JB) return;
    try {
      JB(el, v, {
        format: f, width: 1.4, height: 42, displayValue: true, fontSize: 11,
        font: 'Mulish, sans-serif', textMargin: 2, margin: 2,
        background: '#ffffff', lineColor: '#000000'
      });
    } catch (err) {
      el.outerHTML = '<div class="ss-barcode-error">Barcode inválido: ' + esc(v) + '</div>';
    }
  }
}
